import itertools, sys
input = sys.stdin.readline
n, k = map(int, input().split())
base = set("antic")
words = []
for _ in range(n):
    mask = 0
    for ch in set(input().strip()) - base:
        mask |= 1 << (ord(ch) - 97)
    words.append(mask)
