    print(0)
elif k == 26:
    print(n)
else:
    candidates = [i for i in range(26) if chr(i + 97) not in base]
    ans = 0
    for comb in itertools.combinations(candidates, k - 5):
        teach = 0
        for i in comb:
            teach |= 1 << i
        ans = max(ans, sum((w & ~teach) == 0 for w in words))
    print(ans)

