import sys
n = int(sys.stdin.readline())
s = sys.stdin.readline().strip()
sign = [[""] * n for _ in range(n)]
idx = 0
for i in range(n):
    for j in range(i, n):
        sign[i][j] = s[idx]
        idx += 1
ans = []
def ok(pos):
    total = 0
    for i in range(pos, -1, -1):
        total += ans[i]
        c = sign[i][pos]
        if c == "+" and total <= 0:
            return False
        if c == "-" and total >= 0:
            return False
        if c == "0" and total != 0:
            return False
    return True
def dfs(pos):
    if pos == n:
        print(*ans)
        raise SystemExit
    candidates = [0] if sign[pos][pos] == "0" else (range(1, 11) if sign[pos][pos] == "+" else range(-10, 0))
    for x in candidates:
        ans.append(x)
        if ok(pos):
            dfs(pos + 1)
        ans.pop()
dfs(0)

