def val(ch):
    if ch == "0":
        return 0
    if "a" <= ch <= "z":
        return ord(ch) - 96
    return ord(ch) - 38
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
def union(a, b):
    ra, rb = find(a), find(b)
    if ra == rb:
        return False
    parent[rb] = ra
    return True
