from collections import defaultdict, deque
import sys
g = defaultdict(list)
nodes = set()
for line in sys.stdin:
    if not line.strip():
        continue
    a, b, c = map(int, line.split())
    g[a].append((b, c))
    g[b].append((a, c))
    nodes.add(a); nodes.add(b)
if not nodes:
    print(0)
else:
    def far(start):
        dist = {start: 0}
        q = deque([start])
        while q:
            x = q.popleft()
            for nx, w in g[x]:
                if nx not in dist:
                    dist[nx] = dist[x] + w
                    q.append(nx)
        node = max(dist, key=dist.get)
        return node, dist[node]
    a, _ = far(next(iter(nodes)))
    _, ans = far(a)
    print(ans)

