import bisect, sys
input = sys.stdin.readline
n, m, k = map(int, input().split())
keys = []
values = {}
for _ in range(n):
    key, value = map(int, input().split())
    keys.append(key)
    values[key] = value
keys.sort()
out = []
def nearest(key):
    idx = bisect.bisect_left(keys, key)
    cand = []
    if idx < len(keys):
        cand.append(keys[idx])
    if idx:
        cand.append(keys[idx - 1])
    cand = [x for x in cand if abs(x - key) <= k]
    if not cand:
        return None
    cand.sort(key=lambda x: (abs(x - key), x))
    if len(cand) >= 2 and abs(cand[0] - key) == abs(cand[1] - key):
        return "?"
    return cand[0]
for _ in range(m):
    data = list(map(int, input().split()))
    if data[0] == 1:
        _, key, value = data
        if key not in values:
            bisect.insort(keys, key)
        values[key] = value
    elif data[0] == 2:
        _, key, value = data
        target = nearest(key)
        if isinstance(target, int):
            values[target] = value
    else:
        _, key = data
        target = nearest(key)
        if target is None:
            out.append("-1")
        elif target == "?":
            out.append("?")
        else:
            out.append(str(values[target]))
print("\n".join(out))

