    items.append((idx,x-r,x+r))
a,b=map(int,input().split())
ids=[idx for idx,_,_ in items]
by_id={idx:(l,r) for idx,l,r in items}
parent={idx:0 for idx in ids}
for i,l,r in items:
    best=0
    best_len=10**30
    for j,lj,rj in items:
        if i==j: continue
        if lj<l and r<rj and rj-lj<best_len:
            best=j
            best_len=rj-lj
    parent[i]=best
g={0:[]}
for idx in ids:
    g.setdefault(idx,[])
for idx,p in parent.items():
    g[idx].append(p)
    g.setdefault(p,[]).append(idx)
prev={a:None}
q=deque([a])
while q:
    x=q.popleft()
    if x==b: break
    for y in g[x]:
        if y not in prev:
            prev[y]=x
            q.append(y)
path=[]
cur=b
while cur is not None:
    if cur!=0:
        path.append(cur)
    cur=prev[cur]
path.reverse()
print(len(path))
print(*path)
